import * as THREE from 'three';

/* ============================ tiny utils ============================ */

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const sstep = (e0, e1, x) => {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
};
const wrap01 = v => v - Math.floor(v);
const shortest = (to, from) => (((to - from) % 1) + 1.5) % 1 - 0.5;

function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(1123581321);
const rand = (a = 1, b) => (b === undefined ? rng() * a : a + rng() * (b - a));

function hash2(x, y) { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); }
function vnoise(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
  const a = hash2(ix, iy), b = hash2(ix + 1, iy), c = hash2(ix, iy + 1), d = hash2(ix + 1, iy + 1);
  return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
}
function fbm(x, y) {
  let v = 0, amp = 0.5, f = 1;
  for (let i = 0; i < 3; i++) { v += amp * vnoise(x * f, y * f); f *= 2.17; amp *= 0.5; }
  return v;
}

/* ============================ dom refs ============================ */

const bootEl = document.getElementById('boot');
const fpsEl = document.getElementById('fps');
const bSun = document.getElementById('bSun');
const bRain = document.getElementById('bRain');
const toastEl = document.getElementById('toast');
const helpEl = document.getElementById('help');
document.getElementById('helpClose').addEventListener('click', () => helpEl.classList.remove('open'));
helpEl.addEventListener('click', e => { if (e.target === helpEl) helpEl.classList.remove('open'); });

let toastTimer = 0;
function toast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.remove('show'), 1900);
}

/* ============================ renderer / scene ============================ */

const isCoarse = matchMedia('(pointer: coarse)').matches;
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
} catch (err) {
  bootEl.textContent = 'WebGL is not available in this browser';
  throw err;
}
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, isCoarse ? 1.6 : 2));
renderer.setSize(innerWidth, innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
if ('transmissionResolutionScale' in renderer) renderer.transmissionResolutionScale = 1;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x10151d, 0.04);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 120);

/* uniforms shared across materials (single objects, updated once per frame) */
const uni = {
  time:      { value: 0 },
  sway:      { value: 1 },
  imp:       { value: 0 },
  impDir:    { value: new THREE.Vector3(1, 0, 0) },
  rain:      { value: 0 },
  glow:      { value: 0.4 },
  night:     { value: 0 },
  pr:        { value: renderer.getPixelRatio() },
  sunDir:    { value: new THREE.Vector3(0.4, 0.8, 0.3).normalize() },
  sunCol:    { value: new THREE.Color(1.0, 0.93, 0.8) },
  knock:     { value: new THREE.Vector3(0, 1.4, 0) },
  knockTime: { value: -100 }
};

const ripples = Array.from({ length: 8 }, () => new THREE.Vector4(0, 0, -1000, 0));
let rippleIdx = 0;
function addRipple(x, z, amp) {
  const r = ripples[rippleIdx];
  rippleIdx = (rippleIdx + 1) % 8;
  r.set(x, z, uni.time.value, amp);
}

/* ============================ backdrop & table ============================ */

const bgMat = new THREE.ShaderMaterial({
  uniforms: {
    uTop: { value: new THREE.Color(0x9db6c2) },
    uBot: { value: new THREE.Color(0xd9c9ae) }
  },
  vertexShader: `
    varying vec3 vDir;
    void main() {
      vDir = position;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 uTop;
    uniform vec3 uBot;
    varying vec3 vDir;
    void main() {
      vec3 d = normalize(vDir);
      float h = d.y * 0.5 + 0.5;
      vec3 col = mix(uBot, uTop, smoothstep(0.30, 0.88, h));
      col = mix(col, uBot * 0.5, 1.0 - smoothstep(0.0, 0.32, h));
      float n = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
      col += (n - 0.5) / 160.0;
      gl_FragColor = vec4(col, 1.0);
    }
  `,
  side: THREE.BackSide,
  depthWrite: false,
  fog: false
});
const bg = new THREE.Mesh(new THREE.SphereGeometry(60, 32, 16), bgMat);
bg.renderOrder = -1;
scene.add(bg);

function woodTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const g = c.getContext('2d');
  g.fillStyle = '#3a2c20';
  g.fillRect(0, 0, 512, 512);
  let y = 0;
  while (y < 512) {
    const h = 26 + rng() * 30;
    const sh = 0.8 + rng() * 0.38;
    g.fillStyle = 'rgb(' + Math.round(66 * sh) + ',' + Math.round(51 * sh) + ',' + Math.round(36 * sh) + ')';
    g.fillRect(0, y, 512, h);
    for (let i = 0; i < 22; i++) {
      g.strokeStyle = rng() < 0.5
        ? 'rgba(20,14,8,' + (0.04 + rng() * 0.08).toFixed(3) + ')'
        : 'rgba(122,98,66,' + (0.03 + rng() * 0.07).toFixed(3) + ')';
      g.lineWidth = 0.6 + rng() * 1.6;
      const sy = y + rng() * h;
      g.beginPath();
      g.moveTo(0, sy);
      g.bezierCurveTo(170, sy + rand(-4, 4), 340, sy + rand(-4, 4), 512, sy + rand(-3, 3));
      g.stroke();
    }
    g.fillStyle = 'rgba(0,0,0,0.35)';
    g.fillRect(0, y + h - 1.2, 512, 1.4);
    y += h;
  }
  for (let i = 0; i < 2600; i++) {
    g.fillStyle = rng() < 0.5
      ? 'rgba(0,0,0,' + (rng() * 0.05).toFixed(3) + ')'
      : 'rgba(255,230,200,' + (rng() * 0.045).toFixed(3) + ')';
    g.fillRect(rng() * 512, rng() * 512, 1.2, 1.2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(3, 3);
  tex.anisotropy = 4;
  return tex;
}

function aoTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 256;
  const g = c.getContext('2d');
  const rg = g.createRadialGradient(128, 128, 8, 128, 128, 128);
  rg.addColorStop(0, 'rgba(0,0,0,0.5)');
  rg.addColorStop(0.55, 'rgba(0,0,0,0.24)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = rg;
  g.fillRect(0, 0, 256, 256);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const table = new THREE.Mesh(
  new THREE.CircleGeometry(9, 64),
  new THREE.MeshStandardMaterial({ map: woodTexture(), roughness: 0.82, metalness: 0 })
);
table.rotation.x = -Math.PI / 2;
table.receiveShadow = true;
scene.add(table);

const ao = new THREE.Mesh(
  new THREE.CircleGeometry(1.7, 40),
  new THREE.MeshBasicMaterial({ map: aoTexture(), transparent: true, depthWrite: false })
);
ao.rotation.x = -Math.PI / 2;
ao.position.y = 0.004;
scene.add(ao);

/* procedural environment for the glass to reflect (no external HDR needed) */
(function buildEnvironment() {
  const env = new THREE.Scene();
  const grad = document.createElement('canvas');
  grad.width = 4; grad.height = 256;
  const g = grad.getContext('2d');
  const lg = g.createLinearGradient(0, 0, 0, 256);
  lg.addColorStop(0.0, '#8fa5b8');
  lg.addColorStop(0.5, '#cfc8b8');
  lg.addColorStop(0.62, '#6b5b47');
  lg.addColorStop(1.0, '#241d16');
  g.fillStyle = lg;
  g.fillRect(0, 0, 4, 256);
  const tex = new THREE.CanvasTexture(grad);
  tex.colorSpace = THREE.SRGBColorSpace;
  env.add(new THREE.Mesh(
    new THREE.SphereGeometry(20, 16, 12),
    new THREE.MeshBasicMaterial({ map: tex, side: THREE.BackSide })
  ));
  const panel = (w, h, x, y, z, r, gg, b) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial());
    m.material.color.setRGB(r, gg, b);
    m.position.set(x, y, z);
    m.lookAt(0, 0, 0);
    env.add(m);
  };
  panel(7, 4, -6, 7, 4, 5.5, 5.0, 4.0);
  panel(5, 6, 8, 2.5, -2, 1.1, 1.6, 2.4);
  panel(4, 3, 3, 1.5, 7.5, 1.6, 1.2, 0.8);
  const pm = new THREE.PMREMGenerator(renderer);
  const rt = pm.fromScene(env, 0.045);
  scene.environment = rt.texture;
  scene.environmentIntensity = 0.5;
  pm.dispose();
})();

/* ============================ lights ============================ */

const hemi = new THREE.HemisphereLight(0xb7cdd6, 0x5c4a36, 0.6);
scene.add(hemi);

const dirLight = new THREE.DirectionalLight(0xfff2dc, 2.0);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
const sc = dirLight.shadow.camera;
sc.near = 4; sc.far = 16;
sc.left = -2.6; sc.right = 2.6; sc.top = 3.2; sc.bottom = -2.0;
dirLight.shadow.bias = -0.0004;
dirLight.shadow.normalBias = 0.03;
dirLight.target.position.set(0, 0.9, 0);
scene.add(dirLight, dirLight.target);

const fireflyLight = new THREE.PointLight(0xffc873, 0, 6.5, 2);
fireflyLight.position.set(0, 1.4, 0);
scene.add(fireflyLight);

/* ============================ terrain ============================ */

const DOME_Y = 0.34;
const POND = { x: 0.42, z: -0.06 };

function domeRaw(x, z) {
  const r2 = x * x + z * z;
  return r2 >= 1 ? 0 : 0.5 * Math.sqrt(1 - r2);
}
function terrainRaw(x, z) {
  return DOME_Y + domeRaw(x, z) + (fbm(x * 2.3 + 7.31, z * 2.3 + 2.97) - 0.44) * 0.14;
}
const POND_Y = terrainRaw(POND.x, POND.z) - 0.07;
function terrain(x, z) {
  const raw = terrainRaw(x, z);
  const d = Math.hypot(x - POND.x, z - POND.z);
  const t = sstep(0.46, 0.30, d);
  return raw + (POND_Y - raw) * t;
}

/* soil column + jar floor */
const soil = new THREE.Mesh(
  new THREE.CylinderGeometry(1.0, 1.06, 0.3, 48),
  new THREE.MeshStandardMaterial({ color: 0x3a2b1e, roughness: 1 })
);
soil.position.y = 0.2;
soil.castShadow = soil.receiveShadow = true;
scene.add(soil);

const floorIn = new THREE.Mesh(
  new THREE.CylinderGeometry(1.07, 1.07, 0.06, 48),
  new THREE.MeshStandardMaterial({ color: 0x241a12, roughness: 1 })
);
floorIn.position.y = 0.03;
floorIn.receiveShadow = true;
scene.add(floorIn);

/* displaced mossy dome */
const domeGeo = new THREE.SphereGeometry(1, 64, 32, 0, Math.PI * 2, 0, Math.PI / 2);
{
  const pos = domeGeo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const cSoil = new THREE.Color(0x4a3826);
  const cMoss = new THREE.Color(0x50603c);
  const cVar = new THREE.Color(0x6a7a4a);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const y = terrain(x, z);
    pos.setY(i, y);
    c.lerpColors(cSoil, cMoss, sstep(0.02, 0.34, y - DOME_Y));
    c.lerp(cVar, fbm(x * 5.1 + 3.3, z * 5.1 + 8.8) * 0.35);
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }
  domeGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  domeGeo.computeVertexNormals();
  const nor = domeGeo.attributes.normal;
  const cols = 65;
  for (let i = 0; i < cols; i++) { nor.setXYZ(i, 0, 1, 0); } // pole row
  for (let row = 1; row <= 32; row++) {                       // weld the seam
    const a = row * cols, b = row * cols + cols - 1;
    const nx = (nor.getX(a) + nor.getX(b)) / 2;
    const ny = (nor.getY(a) + nor.getY(b)) / 2;
    const nz = (nor.getZ(a) + nor.getZ(b)) / 2;
    nor.setXYZ(a, nx, ny, nz);
    nor.setXYZ(b, nx, ny, nz);
  }
}
const dome = new THREE.Mesh(
  domeGeo,
  new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0 })
);
dome.castShadow = dome.receiveShadow = true;
scene.add(dome);

/* ============================ glass jar + cork ============================ */

const glassTx = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, metalness: 0, roughness: 0.05,
  transmission: 1, thickness: 0.35, ior: 1.5,
  attenuationColor: new THREE.Color(0xd8eee0), attenuationDistance: 2.6,
  clearcoat: 1, clearcoatRoughness: 0.08,
  specularIntensity: 1, envMapIntensity: 1,
  depthWrite: false, side: THREE.FrontSide
});
const glassCheap = new THREE.MeshPhysicalMaterial({
  color: 0xcfe6dc, metalness: 0, roughness: 0.06,
  transparent: true, opacity: 0.16,
  clearcoat: 1, clearcoatRoughness: 0.1,
  depthWrite: false, side: THREE.FrontSide
});

const jarPts = [
  [0.00, 0.06], [0.55, 0.02], [0.98, 0.02], [1.12, 0.10], [1.15, 0.30],
  [1.15, 1.72], [1.12, 1.95], [0.98, 2.18], [0.78, 2.36], [0.64, 2.48],
  [0.60, 2.58], [0.60, 2.66], [0.66, 2.68], [0.66, 2.74], [0.56, 2.76]
].map(p => new THREE.Vector2(p[0], p[1]));
const glass = new THREE.Mesh(new THREE.LatheGeometry(jarPts, 72), glassTx);
glass.castShadow = glass.receiveShadow = false;
scene.add(glass);

const cork = new THREE.Mesh(
  new THREE.LatheGeometry([
    new THREE.Vector2(0.0, 0.0), new THREE.Vector2(0.50, 0.0), new THREE.Vector2(0.54, 0.05),
    new THREE.Vector2(0.54, 0.24), new THREE.Vector2(0.44, 0.33), new THREE.Vector2(0.28, 0.37),
    new THREE.Vector2(0.0, 0.39)
  ], 40),
  new THREE.MeshStandardMaterial({ color: 0xb28456, roughness: 0.95 })
);
const CORK_Y = 2.72, CORK_TILT = 0.16;
cork.position.set(0.04, CORK_Y, 0);
cork.rotation.set(0.05, 0, CORK_TILT);
cork.castShadow = true;
scene.add(cork);
let corkImp = 0;

/* ============================ pond ============================ */

const pondMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: uni.time, uNight: uni.night,
    uSunDir: uni.sunDir, uSunCol: uni.sunCol,
    uRip: { value: ripples }
  },
  vertexShader: `
    varying vec3 vW;
    void main() {
      vec4 w = modelMatrix * vec4(position, 1.0);
      vW = w.xyz;
      gl_Position = projectionMatrix * viewMatrix * w;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform float uNight;
    uniform vec3 uSunDir;
    uniform vec3 uSunCol;
    uniform vec4 uRip[8];
    varying vec3 vW;
    void main() {
      vec2 q = vW.xz;
      float dhx = cos(q.x * 9.0 + uTime * 1.3) * 0.18 + cos((q.x + q.y) * 7.0 + uTime * 0.7) * 0.09;
      float dhz = cos(q.y * 11.0 - uTime * 1.1) * 0.16 + cos((q.x + q.y) * 7.0 + uTime * 0.7) * 0.09;
      vec3 n = normalize(vec3(-dhx, 1.0, -dhz));
      for (int i = 0; i < 8; i++) {
        vec4 r = uRip[i];
        float age = uTime - r.z;
        if (r.w < 0.001 || age < 0.0 || age > 3.0) continue;
        vec2 dv = q - r.xy;
        float d = max(length(dv), 0.02);
        float w = sin(d * 34.0 - age * 11.0);
        float env = exp(-d * 4.0) * exp(-age * 2.0) * smoothstep(0.0, 0.1, age);
        n = normalize(n + vec3(-dv.x / d, 0.0, -dv.y / d) * w * env * 0.35 * r.w);
      }
      vec3 V = normalize(cameraPosition - vW);
      float fres = pow(1.0 - max(dot(n, V), 0.0), 3.0);
      vec3 deep = mix(vec3(0.05, 0.12, 0.11), vec3(0.008, 0.028, 0.045), uNight);
      vec3 skyT = mix(vec3(0.62, 0.72, 0.78), vec3(0.09, 0.13, 0.22), uNight);
      vec3 col = mix(deep, skyT, fres * 0.9);
      vec3 H = normalize(uSunDir + V);
      float ndh = max(dot(n, H), 0.0);
      col += uSunCol * (pow(ndh, 90.0) * 1.4 + pow(ndh, 400.0) * 2.0);
      gl_FragColor = vec4(col, 0.93);
    }
  `,
  transparent: true,
  depthWrite: false
});
const pond = new THREE.Mesh(new THREE.CircleGeometry(0.30, 48), pondMat);
pond.rotation.x = -Math.PI / 2;
pond.position.set(POND.x, POND_Y + 0.01, POND.z);
scene.add(pond);

/* ============================ vegetation ============================ */

/* wind + knock impulse injected into standard materials */
function addWind(mat, amp, freq) {
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uTime = uni.time;
    sh.uniforms.uSway = uni.sway;
    sh.uniforms.uImp = uni.imp;
    sh.uniforms.uImpDir = uni.impDir;
    sh.vertexShader =
      'uniform float uTime;\nuniform float uSway;\nuniform float uImp;\nuniform vec3 uImpDir;\n' +
      sh.vertexShader.replace(
        '#include <begin_vertex>',
`#include <begin_vertex>
#ifdef USE_INSTANCING
  float wPh = instanceMatrix[3][0] * 3.17 + instanceMatrix[3][2] * 2.71 + instanceMatrix[3][1] * 1.31;
  float wBend = pow(max(position.y, 0.0), 1.35);
  transformed.x += (sin(uTime * ${freq.toFixed(2)} + wPh) * ${amp.toFixed(4)} * uSway) * wBend + uImpDir.x * uImp * 0.22 * wBend;
  transformed.z += (cos(uTime * ${(freq * 0.83).toFixed(2)} + wPh * 1.31) * ${(amp * 0.7).toFixed(4)} * uSway) * wBend + uImpDir.z * uImp * 0.22 * wBend;
#endif`
      );
  };
}

/* rejection-sampled instanced scatterer */
function scatter(geo, mat, count, place, opts) {
  const m = new THREE.InstancedMesh(geo, mat, count);
  const M = new THREE.Matrix4(), Q = new THREE.Quaternion();
  const E = new THREE.Euler(), S = new THREE.Vector3(), P = new THREE.Vector3();
  const C = new THREE.Color();
  let n = 0;
  for (let i = 0; i < count * 40 && n < count; i++) {
    const r = place();
    if (!r) continue;
    E.set(r.tilt || 0, r.yaw || 0, r.roll || 0);
    Q.setFromEuler(E);
    S.set(r.sx !== undefined ? r.sx : r.s, r.sy !== undefined ? r.sy : r.s, r.sz !== undefined ? r.sz : r.s);
    P.set(r.x, r.y, r.z);
    M.compose(P, Q, S);
    m.setMatrixAt(n, M);
    if (r.c) m.setColorAt(n, C.set(r.c));
    n++;
  }
  m.count = n;
  m.instanceMatrix.needsUpdate = true;
  if (m.instanceColor) m.instanceColor.needsUpdate = true;
  m.castShadow = !(opts && opts.noCast);
  m.receiveShadow = !(opts && opts.noReceive);
  m.frustumCulled = false;
  scene.add(m);
  return m;
}

/* -- grass blades -- */
function bladeGeometry() {
  const pos = [], col = [], idx = [];
  const SEG = 3, H = 0.30, W = 0.045;
  const cB = new THREE.Color(0x24401f), cT = new THREE.Color(0x9dc069), c = new THREE.Color();
  for (let i = 0; i <= SEG; i++) {
    const t = i / SEG;
    const y = t * H, z = t * t * H * 0.45;
    const w = W * (1 - t) * (1 - t * 0.4) + 0.003;
    pos.push(-w, y, z, w, y, z);
    c.lerpColors(cB, cT, Math.pow(t, 0.8));
    col.push(c.r, c.g, c.b, c.r, c.g, c.b);
  }
  for (let i = 0; i < SEG; i++) {
    const a = i * 2;
    idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}
const grassMat = new THREE.MeshStandardMaterial({
  vertexColors: true, roughness: 0.85, metalness: 0, side: THREE.DoubleSide
});
addWind(grassMat, 0.05, 1.6);
scatter(bladeGeometry(), grassMat, 760, () => {
  const x = rand(-0.95, 0.95), z = rand(-0.95, 0.95);
  if (x * x + z * z > 0.86) return null;
  if (Math.hypot(x - POND.x, z - POND.z) < 0.50) return null;
  const patch = fbm(x * 3.1 + 11.7, z * 3.1 + 4.2);
  if (rng() > 0.22 + patch * 1.1) return null;
  const s = rand(0.55, 1.45);
  return {
    x, y: terrain(x, z) - 0.015, z,
    yaw: rand(0, Math.PI * 2), tilt: rand(-0.22, 0.22), roll: rand(-0.22, 0.22),
    sx: s * rand(0.75, 1.25), sy: s * rand(0.8, 1.3), sz: s,
