/* -- procedural fern (six fronds baked into one bush geometry) -- */
function buildFern() {
  const pos = [], col = [], idx = [];
  const cBase = new THREE.Color(0x2e4a26), cTip = new THREE.Color(0x8fb75e);
  const tmpC = new THREE.Color();
  const fronds = 6, S = 9, M = 9;
  let vi = 0;
  for (let f = 0; f < fronds; f++) {
    const yaw = (f / fronds) * Math.PI * 2 + rand(-0.2, 0.2);
    const tilt = rand(0.95, 1.25);
    const len = rand(0.5, 0.72);
    const dirX = Math.sin(tilt) * Math.cos(yaw);
    const dirY = Math.cos(tilt);
    const dirZ = Math.sin(tilt) * Math.sin(yaw);
    const sideX = -Math.sin(yaw), sideZ = Math.cos(yaw);
    const drop = rand(0.18, 0.3);
    const px = t => dirX * len * t;
    const py = t => dirY * len * t - drop * len * t * t;
    const pz = t => dirZ * len * t;
    for (let i = 0; i < S; i++) {
      const t0 = i / S, t1 = (i + 1) / S;
      const aX = px(t0), aY = py(t0), aZ = pz(t0);
      const bX = px(t1), bY = py(t1), bZ = pz(t1);
      const w0 = 0.016 * (1 - t0 * 0.55), w1 = 0.016 * (1 - t1 * 0.55);
      pos.push(
        aX - sideX * w0, aY, aZ - sideZ * w0,
        aX + sideX * w0, aY, aZ + sideZ * w0,
        bX + sideX * w1, bY, bZ + sideZ * w1,
        bX - sideX * w1, bY, bZ - sideZ * w1
      );
      tmpC.lerpColors(cBase, cTip, t0 * 0.5).multiplyScalar(0.9);
      for (let k = 0; k < 4; k++) col.push(tmpC.r, tmpC.g, tmpC.b);
      idx.push(vi, vi + 1, vi + 2, vi, vi + 2, vi + 3);
      vi += 4;
    }
    for (let i = 1; i <= M; i++) {
      const t = 0.18 + 0.78 * (i / M);
      const cX = px(t), cY = py(t), cZ = pz(t);
      const L = len * 0.34 * Math.sin(Math.PI * Math.min(1, t * 1.12 + 0.08));
      tmpC.lerpColors(cBase, cTip, Math.min(1, t + 0.15));
      for (let sgi = 0; sgi < 2; sgi++) {
        const sgn = sgi === 0 ? -1 : 1;
        const tipX = cX + sideX * sgn * L;
        const tipY = cY + L * 0.55;
        const tipZ = cZ + sideZ * sgn * L;
        pos.push(cX - 0.014, cY, cZ, cX + 0.014, cY, cZ, tipX, tipY, tipZ);
        for (let k = 0; k < 3; k++) col.push(tmpC.r, tmpC.g, tmpC.b);
        idx.push(vi, vi + 1, vi + 2);
        vi += 3;
      }
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}
