    attribute float aPhase;
    attribute float aSpeed;
    uniform float uTime;
    uniform float uGlow;
    uniform float uPR;
    uniform float uKnockTime;
    uniform vec3 uKnock;
    varying float vA;
    void main() {
      vec3 p = position;
      float t = uTime * aSpeed;
      p.x += sin(t * 0.9 + aPhase) * 0.22;
