const C_SUN_HIGH = new THREE.Color(0xfff3dd), C_SUN_LOW = new THREE.Color(0xff9c54), C_MOON = new THREE.Color(0x8ea9d6);
const H_SKY_D = new THREE.Color(0xb7cdd6), H_SKY_N = new THREE.Color(0x1a2740);
const H_GND_D = new THREE.Color(0x5c4a36), H_GND_N = new THREE.Color(0x0d1118);
const BG_TOP_D = new THREE.Color(0x9db6c2), BG_TOP_N = new THREE.Color(0x05080f);
const BG_BOT_D = new THREE.Color(0xd9c9ae), BG_BOT_N = new THREE.Color(0x121824);
const tmpDir = new THREE.Vector3(), tmpCol = new THREE.Color();
let sunBadgeDay = null;

function applyDay() {
  const ang = dayT * Math.PI * 2;
  const elev = Math.sin(ang);
  const day = sstep(-0.06, 0.24, elev);
  const night = 1 - sstep(-0.24, 0.06, elev);
  const rain = uni.rain.value;

  uni.night.value = night;
  uni.glow.value = 0.15 + 0.85 * night;

  if (elev > -0.04) {
    tmpDir.set(Math.cos(ang) * 0.85, Math.max(elev, 0.03), 0.45).normalize();
    tmpCol.lerpColors(C_SUN_LOW, C_SUN_HIGH, sstep(0.0, 0.5, elev));
    dirLight.intensity = 2.5 * sstep(-0.04, 0.20, elev);
  } else {
    tmpDir.set(-Math.cos(ang) * 0.85, Math.max(-elev, 0.03), -0.45).normalize();
    tmpCol.copy(C_MOON);
    dirLight.intensity = 0.55 * sstep(0.05, 0.30, -elev);
  }
  dirLight.intensity *= 1 - rain * 0.45;
  dirLight.position.copy(tmpDir).multiplyScalar(9);
  dirLight.color.copy(tmpCol);
  uni.sunDir.value.copy(tmpDir);
  uni.sunCol.value.copy(tmpCol);

  hemi.color.lerpColors(H_SKY_D, H_SKY_N, night);
  hemi.groundColor.lerpColors(H_GND_D, H_GND_N, night);
  hemi.intensity = (0.22 + 0.55 * day + 0.12 * night) * (1 - rain * 0.25);

  scene.environmentIntensity = 0.42 * day + 0.13 * night;

  bgMat.uniforms.uTop.value.lerpColors(BG_TOP_D, BG_TOP_N, night);
  bgMat.uniforms.uBot.value.lerpColors(BG_BOT_D, BG_BOT_N, night);
  scene.fog.color.copy(bgMat.uniforms.uBot.value).multiplyScalar(0.85);

  mushCapMat.emissiveIntensity = 0.08 + 1.5 * night;
  fireflyLight.intensity = night * (2.4 + Math.sin(uni.time.value * 7.3) * 0.5 + Math.sin(uni.time.value * 13.7) * 0.35);

  const isDay = day > 0.5;
  if (isDay !== sunBadgeDay) {
    sunBadgeDay = isDay;
    bSun.textContent = isDay ? 'DAY' : 'NIGHT';
  }
}

