el.addEventListener('pointerdown', e => {
  el.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (pointers.size === 1) downInfo = { x: e.clientX, y: e.clientY, t: performance.now(), moved: 0 };
  if (pointers.size === 2) { pinchD = pinchDist(); if (downInfo) downInfo.moved += 10; }
  document.body.classList.add('dragging');
});
el.addEventListener('pointermove', e => {
  const p = pointers.get(e.pointerId);
  if (!p) return;
  const dx = e.clientX - p.x, dy = e.clientY - p.y;
  p.x = e.clientX; p.y = e.clientY;
  if (pointers.size === 1) {
    ctrl.tAz -= dx * 0.0055;
    ctrl.tPol = clamp(ctrl.tPol - dy * 0.0045, 0.22, 1.50);
    if (downInfo) downInfo.moved += Math.abs(dx) + Math.abs(dy);
  } else if (pointers.size === 2) {
    const d = pinchDist();
    if (pinchD > 0 && d > 0) ctrl.tR = clamp(ctrl.tR * pinchD / d, 3.2, 11.5);
    pinchD = d;
    if (downInfo) downInfo.moved += 6;
