/* ============================ main loop ============================ */

let t = 0, lastT = performance.now();
let frames = 0, fAcc = 0, fpsVal = 60, rainRipT = 0, booted = false;

renderer.setAnimationLoop(() => {
  const now = performance.now();
  const dt = Math.min((now - lastT) / 1000, 0.05) || 0.016;
  lastT = now;
  t += dt;
  uni.time.value = t;

  /* day cycle */
  if (dayTween) {
    dayTween.t += dt;
    const k = sstep(0, 1, Math.min(1, dayTween.t / dayTween.dur));
    dayT = wrap01(dayTween.from + shortest(dayTween.to, dayTween.from) * k);
    if (dayTween.t >= dayTween.dur) { dayT = wrap01(dayTween.to); dayTween = null; }
  } else if (cycleAuto) {
    dayT = wrap01(dayT + dt / CYCLE);
  }

  /* rain */
  uni.rain.value += clamp(rainTarget - uni.rain.value, -dt * 0.6, dt * 0.6);
  if (uni.rain.value > 0.03) {
    rainRipT -= dt;
    if (rainRipT <= 0) {
      rainRipT = 0.22 + rng() * 0.5;
      const a = rng() * Math.PI * 2, rr = Math.sqrt(rng()) * 0.24;
      addRipple(POND.x + Math.cos(a) * rr, POND.z + Math.sin(a) * rr, 0.25 + rng() * 0.5);
    }
  }
  glassTx.roughness = 0.05 + uni.rain.value * 0.09;

  /* wind, impulse, cork wobble, firefly lamp */
  uni.sway.value = 1 + uni.rain.value * 0.8;
  uni.imp.value *= Math.exp(-3.0 * dt);
  corkImp *= Math.exp(-5.0 * dt);
  cork.position.y = CORK_Y + corkImp * 0.04 * Math.abs(Math.sin(t * 30));
  cork.rotation.z = CORK_TILT + corkImp * 0.06 * Math.sin(t * 34);
  fireflyLight.position.set(Math.sin(t * 0.13) * 0.35, 1.35 + Math.sin(t * 0.21) * 0.25, Math.cos(t * 0.17) * 0.35);

  applyDay();

  /* camera */
  if (ctrl.auto && pointers.size === 0) ctrl.tAz += dt * 0.1;
  const k = 1 - Math.exp(-dt * 7);
  ctrl.az += (ctrl.tAz - ctrl.az) * k;
  ctrl.pol += (ctrl.tPol - ctrl.pol) * k;
  ctrl.r += (ctrl.tR - ctrl.r) * k;
  camera.position.set(
    ctrl.target.x + ctrl.r * Math.sin(ctrl.pol) * Math.sin(ctrl.az),
    ctrl.target.y + ctrl.r * Math.cos(ctrl.pol),
    ctrl.target.z + ctrl.r * Math.sin(ctrl.pol) * Math.cos(ctrl.az)
  );
  camera.lookAt(ctrl.target);

  renderer.render(scene, camera);

  /* hud */
  frames++; fAcc += dt;
  if (fAcc >= 0.5) {
    fpsVal = frames / fAcc;
    frames = 0; fAcc = 0;
    fpsEl.textContent = Math.round(fpsVal) + ' fps';
    bRain.classList.toggle('on', uni.rain.value > 0.08);
    if (!lowMode && t > 6 && fpsVal < 42) downgrade();
  }

  if (!booted) {
    booted = true;
    bootEl.classList.add('hide');
    setTimeout(() => bootEl.remove(), 900);
    setTimeout(() => toast('tap the glass'), 2600);
  }
});

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  uni.pr.value = renderer.getPixelRatio();
});
